Looking at this Floyd-Warshall kernel, the key characteristic is the loop-carried dependency on `k` (outer loop). The inner `i`/`j` loops are independent within a given `k`, but they read `path[i][k]` and `path[k][j]` which makes pipelining the innermost loop the safe choice.

```cpp
#include "floyd-warshall.h"


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j, k;

  for (k = 0; k < n; k++)
    {
      for(i = 0; i < n; i++)
        for (j = 0; j < n; j++)
        {
#pragma HLS PIPELINE II=1
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
        }
    }

}

extern "C" {
void workload(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

Looking at the Floyd-Warshall algorithm, I'll apply tiling by staging the relevant data for each `k` iteration into local buffers.

For each `k`, the computation `path[i][j] = min(path[i][j], path[i][k] + path[k][j])` reuses:
- `path[k][j]` (the entire k-th row) across all `i`
- `path[i][k]` (the k-th column element) across all `j`

I'll buffer the k-th row locally (reused N times across all `i`), and process each row `i` in tiles, buffering it locally too.

```cpp
#include "floyd-warshall.h"
#include <cstring>


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
    // Local buffer for the current row i being processed
    int row_i[N];

    for (k = 0; k < n; k++)
    {
        // ---- LOAD phase: stage the k-th row into local memory ----
        load_row_k:
        for (j = 0; j < n; j++)
        {
            row_k[j] = path[k][j];
        }

        for (i = 0; i < n; i++)
        {
            // ---- LOAD phase: stage row i into local memory ----
            load_row_i:
            for (j = 0; j < n; j++)
            {
                row_i[j] = path[i][j];
            }

            // scalar reused across all j for this (k,i)
            int path_ik = row_i[k];

            // ---- COMPUTE phase: operate on local buffers ----
            compute_row:
            for (j = 0; j < n; j++)
            {
                int candidate = path_ik + row_k[j];
                row_i[j] = row_i[j] < candidate ? row_i[j] : candidate;
            }

            // ---- STORE phase: write row i back to global memory ----
            store_row_i:
            for (j = 0; j < n; j++)
            {
                path[i][j] = row_i[j];
            }
        }
    }
}

extern "C" {
void workload(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

**Key tiling changes:**
- **`row_k[N]`**: stages the k-th row once per `k` iteration, reused across all `i` iterations (avoids re-reading `path[k][j]` N times).
- **`row_i[N]`**: stages the current row `i` for local compute, separating load/compute/store phases.
- **`path_ik`**: extracts the scalar `path[i][k]` once per row instead of re-reading global memory per `j`.
- The **compute phase** now operates entirely on local buffers (`row_i`, `row_k`) instead of directly on AXI memory, improving memory locality and removing the multiple concurrent AXI accesses that limited the original inner loop.

Looking at the code, I'll apply PIPELINE to the innermost loops (load, compute, store). The compute loop has a potential false dependence concern on `row_i`, but since each `j` index is independent, II=1 is achievable.

```cpp
#include "floyd-warshall.h"
#include <cstring>


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
    // Local buffer for the current row i being processed
    int row_i[N];

    for (k = 0; k < n; k++)
    {
        // ---- LOAD phase: stage the k-th row into local memory ----
        load_row_k:
        for (j = 0; j < n; j++)
        {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
            row_k[j] = path[k][j];
        }

        for (i = 0; i < n; i++)
        {
            // ---- LOAD phase: stage row i into local memory ----
            load_row_i:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
                row_i[j] = path[i][j];
            }

            // scalar reused across all j for this (k,i)
            int path_ik = row_i[k];

            // ---- COMPUTE phase: operate on local buffers ----
            compute_row:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=row_i inter false
                int candidate = path_ik + row_k[j];
                row_i[j] = row_i[j] < candidate ? row_i[j] : candidate;
            }

            // ---- STORE phase: write row i back to global memory ----
            store_row_i:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
                path[i][j] = row_i[j];
            }
        }
    }
}

extern "C" {
void workload(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

Looking at the compute loop, the inner `j` loop has independent iterations (each `row_i[j]` depends only on its own index plus shared scalars). This is ideal for unrolling. I'll unroll by factor 4 (N=180 = 4×45) and partition the arrays cyclically to provide parallel access.

```cpp
#include "floyd-warshall.h"
#include <cstring>


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=4 dim=1
    // Local buffer for the current row i being processed
    int row_i[N];
#pragma HLS ARRAY_PARTITION variable=row_i cyclic factor=4 dim=1

    for (k = 0; k < n; k++)
    {
        // ---- LOAD phase: stage the k-th row into local memory ----
        load_row_k:
        for (j = 0; j < n; j++)
        {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
            row_k[j] = path[k][j];
        }

        for (i = 0; i < n; i++)
        {
            // ---- LOAD phase: stage row i into local memory ----
            load_row_i:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
                row_i[j] = path[i][j];
            }

            // scalar reused across all j for this (k,i)
            int path_ik = row_i[k];

            // ---- COMPUTE phase: operate on local buffers ----
            compute_row:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=row_i inter false
                int candidate = path_ik + row_k[j];
                row_i[j] = row_i[j] < candidate ? row_i[j] : candidate;
            }

            // ---- STORE phase: write row i back to global memory ----
            store_row_i:
            for (j = 0; j < n; j++)
            {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
                path[i][j] = row_i[j];
            }
        }
    }
}

extern "C" {
void workload(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

Looking at this code, the key opportunity for double buffering is the inner loop over `i`, where we load row_i, compute on it, then store it. I'll create ping-pong buffers for row_i so the load of the next row overlaps with compute/store of the current row.

```cpp
#include "floyd-warshall.h"
#include <cstring>


// Load row i into the selected buffer
static void load_row(int path[N + 0][N + 0], int row_i_1[N], int row_i_2[N],
                     int i, int n, int flag)
{
#pragma HLS INLINE off
    load_row_i:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        if (flag == 0)
            row_i_1[j] = path[i][j];
        else
            row_i_2[j] = path[i][j];
    }
}

// Compute on the selected buffer and store result back to global memory
static void compute_store(int path[N + 0][N + 0], int row_k[N],
                          int row_i_1[N], int row_i_2[N],
                          int i, int k, int n, int flag)
{
#pragma HLS INLINE off
    int path_ik = (flag == 0) ? row_i_1[k] : row_i_2[k];

    compute_row:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=row_i_1 inter false
#pragma HLS DEPENDENCE variable=row_i_2 inter false
        if (flag == 0)
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_1[j];
            v = v < candidate ? v : candidate;
            row_i_1[j] = v;
            path[i][j] = v;
        }
        else
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_2[j];
            v = v < candidate ? v : candidate;
            row_i_2[j] = v;
            path[i][j] = v;
        }
    }
}


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=4 dim=1

    // Two local buffers for the row i being processed (ping-pong)
    int row_i_1[N];
#pragma HLS ARRAY_PARTITION variable=row_i_1 cyclic factor=4 dim=1
    int row_i_2[N];
#pragma HLS ARRAY_PARTITION variable=row_i_2 cyclic factor=4 dim=1

    for (k = 0; k < n; k++)
    {
        // ---- LOAD phase: stage the k-th row into local memory ----
        load_row_k:
        for (j = 0; j < n; j++)
        {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
            row_k[j] = path[k][j];
        }

        // ---- Double-buffered pipeline over rows i ----
        // Prologue: load row 0 into buffer 1 (flag 0)
        load_row(path, row_i_1, row_i_2, 0, n, 0);

        row_loop:
        for (i = 0; i < n; i++)
        {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
            int flag = i % 2;

            // Load next row (i+1) into the opposite buffer while we
            // compute/store the current row i. These two operations
            // touch different ping-pong buffers, allowing overlap.
            if (i + 1 < n)
                load_row(path, row_i_1, row_i_2, i + 1, n, (i + 1) % 2);

            compute_store(path, row_k, row_i_1, row_i_2, i, k, n, flag);
        }
    }
}

extern "C" {
void workload(int path[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

**Key changes for double buffering:**

1. **Two ping-pong buffers** `row_i_1` and `row_i_2` replace the single `row_i`, each partitioned identically.

2. **`load_row()` and `compute_store()` accept a `flag` parameter** to select which buffer set they operate on.

3. **Prologue load**: Before the row loop, row 0 is loaded into buffer 1.

4. **Overlapped schedule in the loop**: For each iteration `i`, we issue the load of row `i+1` into the *opposite* buffer while computing/storing row `i` from the current buffer. Since the two functions touch different ping-pong buffers, the scheduler can overlap them.

5. **First/last-tile behavior preserved**: the prologue handles the first row, and the `if (i + 1 < n)` guard prevents loading past the last row.

Looking at this code, I'll apply memory coalescing by converting the global memory pointer to a wide bus type and using wide bus helper functions for burst transfers.

```cpp
#include "floyd-warshall.h"
#include <cstring>
#include "../../../common/mc.h"


// Load row i into the selected buffer
static void load_row(int row_buf[N], int row_i_1[N], int row_i_2[N],
                     int n, int flag)
{
#pragma HLS INLINE off
    load_row_i:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        if (flag == 0)
            row_i_1[j] = row_buf[j];
        else
            row_i_2[j] = row_buf[j];
    }
}

// Compute on the selected buffer and store result back to local out buffer
static void compute_store(int row_k[N], int row_i_1[N], int row_i_2[N],
                          int out_buf[N],
                          int k, int n, int flag)
{
#pragma HLS INLINE off
    int path_ik = (flag == 0) ? row_i_1[k] : row_i_2[k];

    compute_row:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=row_i_1 inter false
#pragma HLS DEPENDENCE variable=row_i_2 inter false
        if (flag == 0)
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_1[j];
            v = v < candidate ? v : candidate;
            row_i_1[j] = v;
            out_buf[j] = v;
        }
        else
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_2[j];
            v = v < candidate ? v : candidate;
            row_i_2[j] = v;
            out_buf[j] = v;
        }
    }
}


void kernel_floyd_warshall(MARS_WIDE_BUS_TYPE *path)
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=4 dim=1

    // Two local buffers for the row i being processed (ping-pong)
    int row_i_1[N];
#pragma HLS ARRAY_PARTITION variable=row_i_1 cyclic factor=4 dim=1
    int row_i_2[N];
#pragma HLS ARRAY_PARTITION variable=row_i_2 cyclic factor=4 dim=1

    // Staging buffers for wide-bus burst transfers
    int load_buf[N];
#pragma HLS ARRAY_PARTITION variable=load_buf cyclic factor=4 dim=1
    int out_buf[N];
#pragma HLS ARRAY_PARTITION variable=out_buf cyclic factor=4 dim=1

    for (k = 0; k < n; k++)
    {
        // ---- LOAD phase: stage the k-th row into local memory ----
        // Burst read row k from global memory (offset in ints = k*n)
        memcpy_wide_bus_read_int(row_k, path, (long)k * n, n);

        // ---- Double-buffered pipeline over rows i ----
        // Prologue: load row 0 into buffer 1 (flag 0)
        memcpy_wide_bus_read_int(load_buf, path, 0L, n);
        load_row(load_buf, row_i_1, row_i_2, n, 0);

        row_loop:
        for (i = 0; i < n; i++)
        {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
            int flag = i % 2;

            // Load next row (i+1) into the opposite buffer while we
            // compute/store the current row i. These two operations
            // touch different ping-pong buffers, allowing overlap.
            if (i + 1 < n)
            {
                memcpy_wide_bus_read_int(load_buf, path, (long)(i + 1) * n, n);
                load_row(load_buf, row_i_1, row_i_2, n, (i + 1) % 2);
            }

            compute_store(row_k, row_i_1, row_i_2, out_buf, k, n, flag);

            // Burst write the computed row i back to global memory
            memcpy_wide_bus_write_int(path, out_buf, (long)i * n, n);
        }
    }
}

extern "C" {
void workload(MARS_WIDE_BUS_TYPE *path)
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem \
    max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_floyd_warshall(path);
}
}
```

**Key changes for memory coalescing:**

1. **Wide bus pointer type**: Changed `int path[N][N]` to `MARS_WIDE_BUS_TYPE *path` (a 512-bit wide bus) in both `workload()` and `kernel_floyd_warshall()`.

2. **Wide bus header**: Added `#include "../../../common/mc.h"` which defines `LARGE_BUS=512`, `MARS_WIDE_BUS_TYPE`, and burst helper functions.

3. **Burst transfers**: 
   - `memcpy_wide_bus_read_int` reads an entire row (`n` ints) at the linear offset `row*n` into a local buffer in one wide burst.
   - `memcpy_wide_bus_write_int` writes the computed row back in one wide burst.
   - Row k is read once per `k` iteration; rows i are read into ping-pong staging buffers and written out after compute.

4. **Updated INTERFACE pragmas**: Added `max_read_burst_length=256` and `max_write_burst_length=256` for longer bursts.

5. **Cyclic array partitioning**: Added partitioning (`factor=4`) to the new staging buffers `load_buf` and `out_buf` to match the unroll factor and avoid memory-port conflicts.

6. **Preserved optimizations**: Double-buffering (ping-pong `row_i_1`/`row_i_2`), pipelining (`II=1`), and unrolling (`factor=4`) are all retained, with global memory accesses now flowing through coalesced burst staging buffers.

The error is that the header `../../../common/mc.h` doesn't exist in the build environment. I'll provide a self-contained wide-bus implementation (defining `LARGE_BUS`, `MARS_WIDE_BUS_TYPE`, and the helper functions) directly in the source so coalescing still works without the missing include.

```cpp
#include "floyd-warshall.h"
#include <cstring>
#include <ap_int.h>

// ---- Self-contained wide-bus definitions (replaces missing mc.h) ----
#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;

// Number of ints per wide bus word
#define INTS_PER_BUS (LARGE_BUS / 32)

// Burst read 'num' ints from wide-bus global memory into local int buffer.
// 'offset' is in units of ints.
static void memcpy_wide_bus_read_int(int *local, MARS_WIDE_BUS_TYPE *bus,
                                     long offset, int num)
{
#pragma HLS INLINE off
    long base_word = offset / INTS_PER_BUS;
    int  base_off  = (int)(offset % INTS_PER_BUS);
    int idx = 0;
    long w = base_word;
    int o = base_off;

    read_loop:
    while (idx < num)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = bus[w];
        inner_read:
        for (; o < INTS_PER_BUS && idx < num; o++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
            ap_uint<32> v = word.range(o * 32 + 31, o * 32);
            local[idx] = (int)v;
            idx++;
        }
        o = 0;
        w++;
    }
}

// Burst write 'num' ints from local int buffer to wide-bus global memory.
// 'offset' is in units of ints.
static void memcpy_wide_bus_write_int(MARS_WIDE_BUS_TYPE *bus, int *local,
                                      long offset, int num)
{
#pragma HLS INLINE off
    long base_word = offset / INTS_PER_BUS;
    int  base_off  = (int)(offset % INTS_PER_BUS);
    int idx = 0;
    long w = base_word;
    int o = base_off;

    write_loop:
    while (idx < num)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = bus[w];
        inner_write:
        for (; o < INTS_PER_BUS && idx < num; o++)
        {
#pragma HLS LOOP_TRIPCOUNT min=1 max=16
            word.range(o * 32 + 31, o * 32) = (ap_uint<32>)local[idx];
            idx++;
        }
        bus[w] = word;
        o = 0;
        w++;
    }
}


// Load row i into the selected buffer
static void load_row(int row_buf[N], int row_i_1[N], int row_i_2[N],
                     int n, int flag)
{
#pragma HLS INLINE off
    load_row_i:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
        if (flag == 0)
            row_i_1[j] = row_buf[j];
        else
            row_i_2[j] = row_buf[j];
    }
}

// Compute on the selected buffer and store result back to local out buffer
static void compute_store(int row_k[N], int row_i_1[N], int row_i_2[N],
                          int out_buf[N],
                          int k, int n, int flag)
{
#pragma HLS INLINE off
    int path_ik = (flag == 0) ? row_i_1[k] : row_i_2[k];

    compute_row:
    for (int j = 0; j < n; j++)
    {
#pragma HLS LOOP_TRIPCOUNT min=N max=N
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=row_i_1 inter false
#pragma HLS DEPENDENCE variable=row_i_2 inter false
        if (flag == 0)
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_1[j];
            v = v < candidate ? v : candidate;
            row_i_1[j] = v;
            out_buf[j] = v;
        }
        else
        {
            int candidate = path_ik + row_k[j];
            int v = row_i_2[j];
            v = v < candidate ? v : candidate;
            row_i_2[j] = v;
            out_buf[j] = v;
        }
    }
}


void kernel_floyd_warshall(MARS_WIDE_BUS_TYPE *path)
{
#pragma HLS INLINE off

    const int n = N;

    int i, j, k;

    // Local buffer for the k-th row (reused across all i)
    int row_k[N];
#pragma HLS ARRAY_PARTITION variable=row_k cyclic factor=4 dim=1

    // Two local buffers for the row i being processed (ping-pong)
    int row_i_1[N];
#pragma HLS ARRAY_PARTITION variable=row_i_1 cyclic factor=4 dim=1
    int row_i_2[N];
#pragma HLS ARRAY_PARTITION variable=row_i_2 cyclic factor=4 dim=1

    // Staging buffers for wide-bus burst transfers
    int load_buf[N];
#pragma HLS ARRAY_PARTITION variable=load_buf cyclic factor=4 dim=1
    int out_buf[N];
